Point = tuple[float, float]


def add(a: Point, b: Point) -> Point:
    return a[0] + b[0], a[1] + b[1]


def sub(a: Point, b: Point) -> Point:
    return a[0] - b[0], a[1] - b[1]


def mul(a: Point, k: float) -> Point:
    return a[0] * k, a[1] * k


def place(p: Point, le: Point, scale_factor: float, chord_axis: Point) -> Point:
    """Isotropic scaling about source LE, then rigid placement on its chord.

    chord_axis is a unit vector from LE to TE; the original source's +Y
    side maps to its clockwise normal, matching the previous GUI orientation.
    All lengths, including local TE thickness, receive one scale factor.
    """
    x,y=p
    ux,uy=chord_axis
    return le[0]+scale_factor*(x*ux+y*uy), le[1]+scale_factor*(x*uy-y*ux)


def dot(a: Point, b: Point) -> float:
    return a[0] * b[0] + a[1] * b[1]


def cross(a: Point, b: Point) -> float:
    return a[0] * b[1] - a[1] * b[0]


def original_half_thickness(t: float) -> float:
    """Original paper NACA 0009 half thickness in millimetres."""
    arc = math.pi * PAPER_RADIUS_MM / 2
    return 5 * 0.09 * arc * (
        0.2969 * math.sqrt(t) - 0.1260 * t - 0.3516 * t*t
        + 0.2843 * t*t*t - 0.1015 * t*t*t*t
    )


def paper_half_thickness(t: float) -> float:
    """Modified source thickness, C2 blended to a 50 mm normal TE gap."""
    base=original_half_thickness(t)
    if t<=TE_BLEND_START:
        return base
    u=min(1.0,max(0.0,(t-TE_BLEND_START)/(1-TE_BLEND_START)))
    weight=u*u*u*(10-15*u+6*u*u)
    return base+(TARGET_TE_GAP_MM/2-original_half_thickness(1.0))*weight


def paper_camber(t: float) -> Point:
    """Source circular mean camber at fractional arc length t, in mm."""
    phi = math.pi * t / 2
    s, c = math.sin(phi), math.cos(phi)
    return (PAPER_CHORD_MM / 2 * (1+s-c),
            PAPER_CHORD_MM / 2 * (s+c-1))


def paper_surface(t: float, sign: int) -> Point:
    """Modified source profile for validation, in the CSV's chord frame."""
    phi = math.pi * t / 2
    s, c = math.sin(phi), math.cos(phi)
    b = paper_camber(t)
    n = ((s-c)/math.sqrt(2), (s+c)/math.sqrt(2))
    return add(b, mul(n, sign * paper_half_thickness(t)))


def nearest_station(p: Point, sign: int) -> tuple[float, float]:
    """Find the paper station underlying an input point, without scipy."""
    def error(t: float) -> float:
        q = paper_surface(t, sign)
        return dot(sub(p, q), sub(p, q))
    count = 400
    j = min(range(count+1), key=lambda i: error(i/count))
    low, high = max(0.0, (j-1)/count), min(1.0, (j+1)/count)
    for _ in range(75):
        a = low + (high-low)*0.381966011250105
        b = high - (high-low)*0.381966011250105
        if error(a) < error(b): high = b
        else: low = a
    t = (low+high)/2
    return t, math.sqrt(error(t))


def load_source() -> dict:
    rows = list(csv.reader(io.StringIO(BASELINE_CSV)))
    if len(rows) != 45 or any(len(row) != 3 for row in rows):
        raise ValueError('Expected exactly the supplied 45 rows of x,y,z')
    points = [tuple(map(float, row)) for row in rows]
    if any(not all(math.isfinite(v) for v in point) or abs(point[2]) > 1e-8
           for point in points):
        raise ValueError('Source contains nonfinite coordinates or nonzero z')
    points_mm = [(x*10, y*10) for x,y,_ in points]
    le_index = min(range(len(points_mm)),key=lambda j: math.hypot(*points_mm[j]))
    if le_index != 22 or math.hypot(*points_mm[le_index]) > 1e-6:
        raise ValueError('Expected upper TE -> LE (row 23) -> lower TE order')
    te_mid = mul(add(points_mm[0], points_mm[-1]), 0.5)
    input_chord = math.dist(te_mid, points_mm[le_index])
    if abs(input_chord-PAPER_CHORD_MM) > 0.05:
        raise ValueError(f'Source chord is {input_chord:.6f} mm; expected {PAPER_CHORD_MM:.6f} mm')
    te_gap=math.dist(points_mm[0],points_mm[-1])
    if abs(te_gap-TARGET_TE_GAP_MM)>0.005:
        raise ValueError(f'Source TE gap is {te_gap:.6f} mm; expected 50 mm')
    # Keep the 45 modified source stations. The analytic formula reconstructs
    # the continuous geometry between points and avoids a spline-fit error.
    stations = []
    errors = []
    for j,p in enumerate(points_mm):
        sign = 1 if j <= le_index else -1
        t, error = nearest_station(p, sign)
        stations.append((t,sign))
        errors.append(error)
    if max(errors)>MAX_CSV_DEVIATION_MM:
        raise ValueError(f'CSV differs from modified baseline by {max(errors):.4f} mm')
    max_normal_thickness=2*max(paper_half_thickness(j/2000)
                               for j in range(2001))
    return dict(stations=stations, source_points=points_mm,
                chord_mm=input_chord, max_reconstruction_error_mm=max(errors),
                te_gap_mm=te_gap,
                max_normal_thickness_mm=max_normal_thickness,
                point_count=len(points_mm), path='embedded 50 mm TE baseline CSV')


def point_segment(p: Point,a: Point,b: Point) -> float:
    v=sub(b,a)
    frac=max(0,min(1,dot(sub(p,a),v)/dot(v,v))) if dot(v,v)>0 else 0
    return math.dist(p,add(a,mul(v,frac)))


def sampled_side(stations: tuple[float,...], sign: int, le: Point,
                 scale_factor: float, chord_axis: Point) -> list[Point]:
    """Refine the same uniformly scaled source for geometric validation."""
    def at(t):return place(paper_surface(t,sign),le,scale_factor,chord_axis)
    def recurse(a,b,pa,pb,depth):
        samples=[a+(b-a)*k for k in (0.25,0.5,0.75)]
        error=max(point_segment(at(t),pa,pb) for t in samples)
        if error>CONTOUR_TOLERANCE_MM:
            if depth>=20:raise ValueError('Contour could not meet sampling tolerance')
            mid=(a+b)/2;pm=at(mid)
            return recurse(a,mid,pa,pm,depth+1)[:-1]+recurse(mid,b,pm,pb,depth+1)
        return [pa,pb]
    result=[at(stations[0])]
    for a,b in zip(stations,stations[1:]):
        result.extend(recurse(a,b,at(a),at(b),0)[1:])
    return result


def validation_contour(le: Point, scale_factor: float,
                       chord_axis: Point) -> list[Point]:
    """Fine analytic paper outline; exported CSV still uses exact 45 source rows."""
    stations=tuple((1-math.cos(math.pi*j/40))/2 for j in range(41))
    upper=sampled_side(tuple(reversed(stations)),1,le,scale_factor,chord_axis)
    lower=sampled_side(stations,-1,le,scale_factor,chord_axis)
    return upper+lower[1:]


def unit_ray(angle_from_vertical_deg: float) -> Point:
    """Ray from O, angle measured from downward vertical toward +X."""
    angle=math.radians(angle_from_vertical_deg)
    return math.sin(angle),-math.cos(angle)


def outer_wall_ray_distance(ray: Point) -> float:
    """Exact first hit of a southeast ray with the outer straight/round wall."""
    h,r=DRAWING_LIMIT_MM,PAPER_RADIUS_MM
    ux,uy=ray
    candidates=[]
    if uy < -1e-12:
        t=-h/uy
        if -1e-7 <= t*ux <= h-r+1e-7:candidates.append(t)
    if ux > 1e-12:
        t=h/ux
        if -h+r-1e-7 <= t*uy <= 1e-7:candidates.append(t)
    centre=(h-r,-h+r)
    b=dot(ray,centre)
    disc=b*b-dot(centre,centre)+r*r
    if disc>=0:
        for t in (b-math.sqrt(disc),b+math.sqrt(disc)):
            p=mul(ray,t)
            if t>0 and p[0]>=h-r-1e-7 and p[1]<=-h+r+1e-7:
                candidates.append(t)
    if not candidates:
        raise ValueError('Ray does not intersect the dimensioned outer wall')
    return min(candidates)


def midline_wall_clearance(p: Point, outer: bool) -> tuple[float, Point]:
    """First wall hit from p on a line PARALLEL to the -45° corner midline.

    The inner measurement points inward (-45° reversed); the outer points
    outward. The fillets use exact circle intersections, not polygon samples.
    This is a directional gap, generally not the shortest local wall normal.
    """
    q=1/math.sqrt(2)
    direction=(q,-q) if outer else (-q,q)
    h,r=DRAWING_LIMIT_MM,PAPER_RADIUS_MM
    candidates=[]

    def vertical(x: float, y_min: float, y_max: float) -> None:
        s=(x-p[0])/direction[0]
        foot=add(p,mul(direction,s))
        if s>=-1e-7 and y_min-1e-7<=foot[1]<=y_max+1e-7:
            candidates.append((max(s,0.0),foot))

    def horizontal(y: float, x_min: float, x_max: float) -> None:
        s=(y-p[1])/direction[1]
        foot=add(p,mul(direction,s))
        if s>=-1e-7 and x_min-1e-7<=foot[0]<=x_max+1e-7:
            candidates.append((max(s,0.0),foot))

    def arc(centre: Point) -> None:
        relative=sub(p,centre)
        b=dot(relative,direction)
        discriminant=b*b-dot(relative,relative)+r*r
        if discriminant<-1e-7:
            return
        root=math.sqrt(max(0.0,discriminant))
        for s in (-b-root,-b+root):
            foot=add(p,mul(direction,s))
            radial=sub(foot,centre)
            if s>=-1e-7 and radial[0]>=-1e-7 and radial[1]<=1e-7:
                candidates.append((max(s,0.0),foot))

    if outer:
        vertical(h,-h+r,4000)
        horizontal(-h,-4000,h-r)
        arc((h-r,-h+r))
    else:
        vertical(r,0,4000)
        horizontal(-r,-4000,0)
        arc((0.0,0.0))
    if not candidates:
        raise ValueError('Midline-parallel line misses the designated corner wall')
    return min(candidates,key=lambda candidate:candidate[0])


def layout(source: dict) -> dict:
    """Baseline camber midpoints and 45° midline-parallel wall gaps."""
    q=1/math.sqrt(2)
    axis=(q,q)
    radii=[FIRST_STATION_RADIUS_MM+i*PITCH_MM for i in range(NUMBER_OF_VANES)]
    baseline=[]
    for radius in radii:
        station=(radius*q,-radius*q)
        le=sub(station,mul(axis,source['chord_mm']/2))
        te=add(station,mul(axis,source['chord_mm']/2))
        midpoint=place(paper_camber(0.5),le,1.0,axis)
        baseline.append(dict(station=station,le=le,te=te,
                             camber_midpoint=midpoint))
    inner,inner_foot=midline_wall_clearance(baseline[0]['camber_midpoint'],False)
    outer,outer_foot=midline_wall_clearance(baseline[-1]['camber_midpoint'],True)
    inner_le=math.hypot(*baseline[0]['le'])-PAPER_RADIUS_MM
    outer_le_point=baseline[-1]['le']
    outer_le_radius=math.hypot(*outer_le_point)
    outer_le=(outer_wall_ray_distance(mul(outer_le_point,1/outer_le_radius))
              -outer_le_radius)
    if min(inner,outer,inner_le,outer_le)<=0:
        raise ValueError('Baseline camber midpoints or leading edges do not fit between the walls')
    return dict(radii=radii,baseline=baseline,
                inner_camber_gap_mm=inner,outer_camber_gap_mm=outer,
                inner_le_gap_mm=inner_le,outer_le_gap_mm=outer_le,
                inner_wall_foot=inner_foot,outer_wall_foot=outer_foot)


def outer_surface_point_gap(p: Point) -> float:
    """Exact nearest distance from a point inside the outer rounded boundary."""
    x,y=p
    h,r=DRAWING_LIMIT_MM,PAPER_RADIUS_MM
    cx,cy=h-r,-h+r
    if x<0 or x>=h or y>0 or y<=-h:
        return -float('inf')
    relative=(x-cx,y-cy)
    if x>cx and y<cy and math.hypot(*relative)>=r:
        return -float('inf')
    distance=min(point_segment(p,(h,cy),(h,4000)),
                 point_segment(p,(-4000,-h),(cx,-h)))
    angle=math.atan2(relative[1],relative[0])
    if -math.pi/2<=angle<=0:
        distance=min(distance,abs(math.hypot(*relative)-r))
    return distance


def optimize_end_stations(source: dict, ray_le: Point, ray_te: Point,
                          normal_projection: dict) -> tuple[float,float,float,dict]:
    """Fit both wall gaps to one equal inter-vane interval in each family.

    Both end stations are limited by complete-airfoil wall clearance, not
    solely by the three reference points. No SciPy or sidecar data is needed.
    """
    q=1/math.sqrt(2)
    chord_axis=(q,q)
    template_le=mul(ray_le,1/normal_projection['le'])
    template_te=mul(ray_te,1/normal_projection['te'])
    template_chord=math.dist(template_le,template_te)
    scale_per_station=template_chord/source['chord_mm']
    template_camber_points=[place(paper_camber(j/30),template_le,
                                  scale_per_station,chord_axis)
                            for j in range(31)]
    template_camber=template_camber_points[15]
    point_vectors={'LE':template_le,'Camber':template_camber,'TE':template_te}
    lengths={name:math.hypot(*vector) for name,vector in point_vectors.items()}
    ray_outer_hits={name:outer_wall_ray_distance(ray)
                    for name,ray in (('LE',ray_le),('TE',ray_te))}
    # Dense analytic outline at a unit bisector station. Every later outline
    # is a scalar multiple of these points, since all chord directions agree.
    template_contour=[place(paper_surface(j/150,sign),template_le,
                            scale_per_station,chord_axis)
                      for sign in (+1,-1) for j in range(151)]
    if any(x<=0 or y>=0 for x,y in template_contour):
        raise ValueError('Airfoil cannot stay in the central corner rectangle at these angles')
    floor=MIN_SURFACE_WALL_GAP_MM+SURFACE_BOUNDARY_MARGIN_MM
    lower=(PAPER_RADIUS_MM+floor)/min(math.hypot(*p) for p in template_contour)
    radial_upper=min(outer_wall_ray_distance(mul(p,1/math.hypot(*p)))
                     /math.hypot(*p) for p in template_contour)
    if radial_upper<=lower:
        raise ValueError('No space for the complete airfoil with the wall-clearance floor')

    def outer_contour_gap(station: float) -> float:
        return min(outer_surface_point_gap(mul(p,station))
                   for p in template_contour)

    if outer_contour_gap(lower)<floor:
        raise ValueError('No feasible end stations with the full-surface wall-clearance floor')
    lo,hi=lower,radial_upper
    for _ in range(48):
        middle=(lo+hi)/2
        if outer_contour_gap(middle)>=floor:
            lo=middle
        else:
            hi=middle
    upper=(lo+hi)/2
    if upper-lower<GEOMETRY_GUARD_MM:
        raise ValueError('No usable span for five separated vanes')

    def metrics(first: float,last: float) -> dict | None:
        if not lower<=first<last<=upper:
            return None
        try:
            camber_rows=[(midline_wall_clearance(mul(vector,first),False)[0],
                          (last-first)/(NUMBER_OF_VANES-1)*dot(vector,(q,-q)),
                          midline_wall_clearance(mul(vector,last),True)[0])
                         for vector in template_camber_points]
        except ValueError:
            return None
        radial_rows={name:(first/normal_projection[name.lower()]-PAPER_RADIUS_MM,
                           (last-first)/(NUMBER_OF_VANES-1)/normal_projection[name.lower()],
                           ray_outer_hits[name]-last/normal_projection[name.lower()])
                     for name in ('LE','TE')}
        rows=camber_rows+list(radial_rows.values())
        if min(min(row) for row in rows)<=0:
            return None
        spacings={name:(last-first)*lengths[name]/(NUMBER_OF_VANES-1)
                  for name in point_vectors}
        # Each family has one third of the weight: camber is the mean across
        # 31 stations, then LE and TE each contribute one row. Both wall gaps
        # must approach the SAME interval. A pair-only term could make two
        # wall gaps equal while both remain very different from vane spacing.
        wall_mismatch=max(abs(inner-outer) for inner,_,outer in rows)
        def row_error(row: tuple[float,float,float]) -> float:
            inner,pitch,outer=row
            return (((inner-pitch)/PITCH_MM)**2+
                    ((outer-pitch)/PITCH_MM)**2)
        score=(sum(row_error(row) for row in camber_rows)/len(camber_rows)+
               row_error(radial_rows['LE'])+row_error(radial_rows['TE']))/3
        family_rms={
            'Camber':PITCH_MM*math.sqrt(sum(row_error(row) for row in camber_rows)
                                             /(2*len(camber_rows))),
            'LE':PITCH_MM*math.sqrt(row_error(radial_rows['LE'])/2),
            'TE':PITCH_MM*math.sqrt(row_error(radial_rows['TE'])/2),
        }
        return dict(score=score,wall_mismatch_mm=wall_mismatch,
                    rms_gap_error_mm=PITCH_MM*math.sqrt(score/2),
                    family_rms_mm=family_rms,
                    camber_rows=camber_rows,radial_rows=radial_rows,
                    spacings=spacings)

    # Coarse global scan followed by deterministic local refinement in mm.
    best=(float('inf'),0.0,0.0,None)
    for i in range(41):
        first=lower+(upper-lower)*i/40
        for j in range(i+1,41):
            last=lower+(upper-lower)*j/40
            result=metrics(first,last)
            if result is not None and result['score']<best[0]:
                best=(result['score'],first,last,result)
    if best[3] is None:
        raise ValueError('No station pair satisfies the whole-camber wall constraints')
    score,first,last,result=best
    step=(upper-lower)/20
    for _ in range(50):
        improved=False
        for di in (-1,0,1):
            for dj in (-1,0,1):
                if not (di or dj):
                    continue
                candidate_first=max(lower,min(upper,first+di*step))
                candidate_last=max(lower,min(upper,last+dj*step))
                candidate=metrics(candidate_first,candidate_last)
                if candidate is not None and candidate['score']<score:
                    score,first,last,result=(candidate['score'],candidate_first,
                                             candidate_last,candidate)
                    improved=True
        if not improved:
            step/=2
        if step<0.0001:
            break
    result['safe_station_bounds_mm']=(lower,upper)
    result['max_possible_row_spacings_mm']={
        name:(upper-lower)*lengths[name]/(NUMBER_OF_VANES-1)
        for name in point_vectors}
    return first,last,score,result


def design(theta_deg: float, source: dict,
           le_angle_deg: float=DEFAULT_LE_ANGLE_DEG) -> dict:
    if not math.isfinite(theta_deg) or not GUI_MIN_THETA_DEG<=theta_deg<=GUI_MAX_THETA_DEG:
        raise ValueError('Theta must be between 0 and 40 degrees')
    if not math.isfinite(le_angle_deg) or not GUI_MIN_LE_ANGLE_DEG<=le_angle_deg<=GUI_MAX_LE_ANGLE_DEG:
        raise ValueError('LE angle must be between 0 and 90 degrees from vertical')
    if theta_deg>0 and le_angle_deg+theta_deg>90:
        raise ValueError('LE angle + theta must be at most 90° to stay in the corner')
    reference_only=theta_deg==0
    baseline=layout(source)
    q=1/math.sqrt(2)
    base_axis=(q,q)
    normal=(q,-q)
    ray_le=unit_ray(le_angle_deg)
    ray_te=unit_ray(le_angle_deg+theta_deg)
    if not reference_only:
        rays={'le':ray_le,'te':ray_te}
        normal_projection={edge:dot(normal,ray) for edge,ray in rays.items()}
        if min(normal_projection.values())<=0:
            raise ValueError('The corner rays cannot intersect the parallel chord lines')
        inner_station,outer_station,optimization_score,optimization_metrics=(
            optimize_end_stations(source,ray_le,ray_te,normal_projection))
        chord_pitch=(outer_station-inner_station)/(NUMBER_OF_VANES-1)
        station_radii=[inner_station+i*chord_pitch for i in range(NUMBER_OF_VANES)]
    else:
        normal_projection=None
        optimization_score=optimization_metrics=None
        chord_pitch=PITCH_MM
        station_radii=baseline['radii']

    vanes=[]
    for i,base in enumerate(baseline['baseline']):
        station_r=station_radii[i]
        station=mul(normal,station_r)
        if reference_only:
            le,te=base['le'],base['te']
        else:
            le=mul(ray_le,station_r/normal_projection['le'])
            te=mul(ray_te,station_r/normal_projection['te'])
        chord=math.dist(le,te)
        if chord<=1e-9:
            raise ValueError(f'Vane {i+1}: chord must be positive')
        chord_axis=mul(sub(te,le),1/chord)
        if abs(cross(chord_axis,base_axis))>1e-9 or dot(chord_axis,base_axis)<0:
            raise ValueError(f'Vane {i+1}: chord is not parallel to the baseline')
        scale_factor=chord/source['chord_mm']
        # One isotropic scale; the source and all new chord axes are parallel.
        contour=[place(p,le,scale_factor,chord_axis)
                 for p in source['source_points']]
        fine=validation_contour(le,scale_factor,chord_axis)
        mean_camber=[place(paper_camber(j/30),le,scale_factor,chord_axis)
                     for j in range(31)]
        camber_midpoint=place(paper_camber(0.5),le,scale_factor,chord_axis)
        if math.dist(mul(add(contour[0],contour[-1]),0.5),te)>1e-6:
            raise ValueError(f'Vane {i+1}: scaled TE midpoint misses its ray')
        midpoint=mul(add(le,te),0.5)
        vanes.append(dict(index=i+1,station=station,
            station_r_mm=station_r,midpoint=midpoint,le=le,te=te,
            mean_camber=mean_camber,camber_midpoint=camber_midpoint,
            placement_fraction=i/(NUMBER_OF_VANES-1),
            chord_mm=chord,scale_factor=scale_factor,
            chord_angle_deg=math.degrees(math.atan2(chord_axis[1],chord_axis[0])),
            rotation_deg=math.degrees(math.atan2(chord_axis[1],chord_axis[0]))-45,
            max_normal_thickness_mm=source['max_normal_thickness_mm']*scale_factor,
            te_gap_mm=source['te_gap_mm']*scale_factor,
            contour=contour,validation_contour=fine,
            baseline_le=base['le'],baseline_te=base['te']))

    if not reference_only:
        for edge,ray in (('le',ray_le),('te',ray_te)):
            for v in vanes:
                if abs(cross(ray,v[edge]))>1e-6:
                    raise ValueError(f'{edge.upper()} points do not share their ray')
        measured=math.degrees(math.atan2(cross(ray_le,ray_te),dot(ray_le,ray_te)))
        if abs(measured-theta_deg)>1e-8:
            raise ValueError('Measured included angle does not match theta')
    else:
        measured=None
    actual_inner_gap,inner_foot=midline_wall_clearance(vanes[0]['camber_midpoint'],False)
    actual_outer_gap,outer_foot=midline_wall_clearance(vanes[-1]['camber_midpoint'],True)
    actual_inner_le=math.hypot(*vanes[0]['le'])-PAPER_RADIUS_MM
    actual_inner_te=math.hypot(*vanes[0]['te'])-PAPER_RADIUS_MM
    actual_outer_le_point=vanes[-1]['le']
    actual_outer_le_radius=math.hypot(*actual_outer_le_point)
    outer_le_ray=mul(actual_outer_le_point,1/actual_outer_le_radius)
    actual_outer_le=(outer_wall_ray_distance(outer_le_ray)-actual_outer_le_radius)
    actual_outer_te_point=vanes[-1]['te']
    actual_outer_te_radius=math.hypot(*actual_outer_te_point)
    outer_te_ray=mul(actual_outer_te_point,1/actual_outer_te_radius)
    actual_outer_te=(outer_wall_ray_distance(outer_te_ray)-actual_outer_te_radius)
    inner_le_wall_foot=mul(vanes[0]['le'],PAPER_RADIUS_MM/math.hypot(*vanes[0]['le']))
    inner_te_wall_foot=mul(vanes[0]['te'],PAPER_RADIUS_MM/math.hypot(*vanes[0]['te']))
    outer_le_wall_foot=mul(outer_le_ray,outer_wall_ray_distance(outer_le_ray))
    outer_te_wall_foot=mul(outer_te_ray,outer_wall_ray_distance(outer_te_ray))
    point_wall_gaps={'LE':{'inner':actual_inner_le,'outer':actual_outer_le},
                     'Camber':{'inner':actual_inner_gap,'outer':actual_outer_gap},
                     'TE':{'inner':actual_inner_te,'outer':actual_outer_te}}
    bisector=(q,-q)
    if (abs(cross(sub(inner_foot,vanes[0]['camber_midpoint']),bisector))>1e-6 or
        abs(cross(sub(outer_foot,vanes[-1]['camber_midpoint']),bisector))>1e-6):
        raise ValueError('A wall-clearance line is not parallel to the corner midline')
    chord_gaps=[b['station_r_mm']-a['station_r_mm']
                for a,b in zip(vanes,vanes[1:])]
    if max(chord_gaps)-min(chord_gaps)>1e-6:
        raise ValueError('Parallel chord lines do not have equal pitch')
    finite_chord_gaps=[segment_gap(a['le'],a['te'],b['le'],b['te'])
                       for a,b in zip(vanes,vanes[1:])]
    point_rows={'LE':'le','Camber':'camber_midpoint','TE':'te'}
    row_intervals={name:[math.dist(a[key],b[key]) for a,b in zip(vanes,vanes[1:])]
                   for name,key in point_rows.items()}
    for name,intervals in row_intervals.items():
        if max(intervals)-min(intervals)>1e-6:
            raise ValueError(f'{name} row has unequal vane-to-vane intervals')
    row_spacings={name:sum(intervals)/len(intervals)
                  for name,intervals in row_intervals.items()}
    camber_station_intervals=[
        [math.dist(a['mean_camber'][j],b['mean_camber'][j])
         for a,b in zip(vanes,vanes[1:])]
        for j in range(31)]
    if any(max(intervals)-min(intervals)>1e-6
           for intervals in camber_station_intervals):
        raise ValueError('A mean-camber station has unequal vane-to-vane intervals')
    camber_station_spacings=[sum(intervals)/len(intervals)
                             for intervals in camber_station_intervals]
    camber_six_gaps=[]
    camber_end_wall_feet={}
    for j in range(31):
        points=[v['mean_camber'][j] for v in vanes]
        inner,inner_wall_foot=midline_wall_clearance(points[0],False)
        outer,outer_wall_foot=midline_wall_clearance(points[-1],True)
        if j in (0,15,30):
            camber_end_wall_feet[str(j)]={'inner':inner_wall_foot,
                                           'outer':outer_wall_foot}
        projected=[dot(sub(b,a),bisector) for a,b in zip(points,points[1:])]
        if max(projected)-min(projected)>1e-6:
            raise ValueError('Projected camber intervals are not equal')
        camber_six_gaps.append([inner,*projected,outer])
    if not reference_only:
        for name,spacing in row_spacings.items():
            if abs(spacing-optimization_metrics['spacings'][name])>1e-6:
                raise ValueError('Optimizer row spacing differs from generated geometry')
        if any(abs(camber_six_gaps[j][k] - expected[0 if k==0 else 2 if k==5 else 1])>1e-6
               for j,expected in enumerate(optimization_metrics['camber_rows'])
               for k in range(6)):
            raise ValueError('Optimizer six-gap metric differs from generated geometry')
    radial_six_gaps={name:[point_wall_gaps[name]['inner'],
                           *([row_spacings[name]]*(NUMBER_OF_VANES-1)),
                           point_wall_gaps[name]['outer']]
                     for name in ('LE','TE')}
    if not reference_only and any(
            abs(radial_six_gaps[name][k]-expected[0 if k==0 else 2 if k==5 else 1])>1e-6
            for name,expected in optimization_metrics['radial_rows'].items()
            for k in range(6)):
        raise ValueError('Optimizer LE/TE-ray gaps differ from generated geometry')
    camber_symmetry_mm=max(max(abs(gaps[0]-gaps[1]),abs(gaps[5]-gaps[1]))
                           for gaps in camber_six_gaps)
    coarse_pair_mismatch_mm=max(
        [abs(gaps[0]-gaps[5]) for gaps in camber_six_gaps]+
        [abs(gaps[0]-gaps[5]) for gaps in radial_six_gaps.values()])
    if not reference_only and abs(coarse_pair_mismatch_mm-optimization_metrics['wall_mismatch_mm'])>1e-6:
        raise ValueError('Optimizer wall imbalance differs from generated geometry')
    # Denser check catches extrema between the 31 optimizer stations.
    inner_vane,outer_vane=vanes[0],vanes[-1]
    dense_camber_rows=[]
    for j in range(301):
        t=j/300
        inner_point=place(paper_camber(t),inner_vane['le'],
                          inner_vane['scale_factor'],base_axis)
        outer_point=place(paper_camber(t),outer_vane['le'],
                          outer_vane['scale_factor'],base_axis)
        inner_gap=midline_wall_clearance(inner_point,False)[0]
        outer_gap=midline_wall_clearance(outer_point,True)[0]
        interval=dot(sub(outer_point,inner_point),bisector)/(NUMBER_OF_VANES-1)
        dense_camber_rows.append((inner_gap,interval,outer_gap))
    camber_wall_pair_mismatch_mm=max(abs(inner-outer)
                                      for inner,_,outer in dense_camber_rows)
    radial_wall_pair_mismatch_mm=max(abs(gaps[0]-gaps[5])
                                     for gaps in radial_six_gaps.values())
    wall_pair_mismatch_mm=max(camber_wall_pair_mismatch_mm,
                              radial_wall_pair_mismatch_mm)
    max_wall_to_spacing_mismatch_mm=max(
        max(abs(inner-interval),abs(outer-interval))
        for inner,interval,outer in dense_camber_rows+
            [(gaps[0],gaps[1],gaps[5]) for gaps in radial_six_gaps.values()])
    return dict(theta_deg=theta_deg,le_angle_deg=le_angle_deg,
        reference_only=reference_only,measured_theta_deg=measured,
        source_chord_mm=source['chord_mm'],source_te_gap_mm=source['te_gap_mm'],
        source_max_normal_thickness_mm=source['max_normal_thickness_mm'],
        baseline_pitch_mm=PITCH_MM,chord_gap_mm=chord_pitch,
        chord_gaps_mm=chord_gaps,finite_chord_gaps_mm=finite_chord_gaps,
        row_spacings_mm=row_spacings,row_intervals_mm=row_intervals,
        camber_station_spacing_range_mm=(min(camber_station_spacings),
                                         max(camber_station_spacings)),
        camber_six_gaps_mm={'LE':camber_six_gaps[0],
                            'Midpoint':camber_six_gaps[15],
                            'TE_midpoint':camber_six_gaps[30]},
        radial_six_gaps_mm=radial_six_gaps,
        camber_end_wall_feet=camber_end_wall_feet,
        camber_max_gap_mismatch_mm=camber_symmetry_mm,
        camber_wall_pair_mismatch_mm=camber_wall_pair_mismatch_mm,
        radial_wall_pair_mismatch_mm=radial_wall_pair_mismatch_mm,
        wall_pair_mismatch_mm=wall_pair_mismatch_mm,
        max_wall_to_spacing_mismatch_mm=max_wall_to_spacing_mismatch_mm,
        spacing_match_met=(not reference_only and max_wall_to_spacing_mismatch_mm<=WALL_EQUALITY_TOLERANCE_MM),
        wall_equality_met=(not reference_only and wall_pair_mismatch_mm<=WALL_EQUALITY_TOLERANCE_MM),
        wall_equality_tolerance_mm=WALL_EQUALITY_TOLERANCE_MM,
        point_wall_gaps_mm=point_wall_gaps,
        optimization_score=optimization_score,
        rms_gap_error_mm=(optimization_metrics['rms_gap_error_mm']
                          if optimization_metrics else None),
        family_gap_rms_mm=(optimization_metrics['family_rms_mm']
                           if optimization_metrics else None),
        max_possible_row_spacings_mm=(optimization_metrics['max_possible_row_spacings_mm']
                                      if optimization_metrics else None),
        surface_wall_floor_mm=MIN_SURFACE_WALL_GAP_MM,
        inner_midline_foot=inner_foot,outer_midline_foot=outer_foot,
        inner_le_wall_foot=inner_le_wall_foot,outer_le_wall_foot=outer_le_wall_foot,
        inner_te_wall_foot=inner_te_wall_foot,outer_te_wall_foot=outer_te_wall_foot,
        inner_chord_mm=vanes[0]['chord_mm'],vanes=vanes)


def walls() -> list[list[Point]]:
    """Physical wall segments read from the dimensioned top-view drawing."""
    h=DRAWING_LIMIT_MM
    r=PAPER_RADIUS_MM
    # The black point in the supplied drawing is the CENTRE of this inner
    # fillet, not the virtual intersection of two walls tangent to a different
    # circle. It goes from (r,0) to (0,-r) about O=(0,0).
    inner=[(r,4000),(r,0)]
    inner += [(r*math.cos(math.pi*j/320),-r*math.sin(math.pi*j/320))
              for j in range(1,161)]
    inner += [(-4000,-r)]
    outer_arc=[(h-r+r*math.cos(math.radians(-90+90*j/160)),
                -h+r+r*math.sin(math.radians(-90+90*j/160))) for j in range(161)]
    return [inner,outer_arc,[(h-r,-h),(-4000,-h)],[(h,-h+r),(h,4000)],
            [(h,4000),(r,4000)], [(-4000,-h),(-4000,-r)]]


def segments(points: list[Point], closed: bool=False):
    return list(zip(points,points[1:]+([points[0]] if closed else [])))


def on_segment(p: Point,a: Point,b: Point,eps: float=1e-8) -> bool:
    return abs(cross(sub(b,a),sub(p,a)))<eps and dot(sub(p,a),sub(p,b))<=eps


def crosses(a: Point,b: Point,c: Point,d: Point) -> bool:
    ab1,ab2=cross(sub(b,a),sub(c,a)),cross(sub(b,a),sub(d,a))
    cd1,cd2=cross(sub(d,c),sub(a,c)),cross(sub(d,c),sub(b,c))
    eps=1e-8
    if ab1*ab2 < -eps and cd1*cd2 < -eps:
        return True
    return ((abs(ab1)<eps and on_segment(c,a,b)) or
            (abs(ab2)<eps and on_segment(d,a,b)) or
            (abs(cd1)<eps and on_segment(a,c,d)) or
            (abs(cd2)<eps and on_segment(b,c,d)))


def segment_gap(a: Point,b: Point,c: Point,d: Point) -> float:
    if crosses(a,b,c,d):return 0.0
    return min(point_segment(a,c,d),point_segment(b,c,d),
               point_segment(c,a,b),point_segment(d,a,b))


def poly_gap(p: list[Point], q: list[Point], closed_p: bool=True,
             closed_q: bool=True) -> float:
    result=float('inf')
    qq=[(a,b,(min(a[0],b[0]),min(a[1],b[1]),max(a[0],b[0]),max(a[1],b[1])))
        for a,b in segments(q,closed_q)]
    for a,b in segments(p,closed_p):
        ax0,ay0,ax1,ay1=min(a[0],b[0]),min(a[1],b[1]),max(a[0],b[0]),max(a[1],b[1])
        for c,d,(cx0,cy0,cx1,cy1) in qq:
            if ax0>cx1+result or cx0>ax1+result or ay0>cy1+result or cy0>ay1+result:
                continue
            result=min(result,segment_gap(a,b,c,d))
            if result<1e-7:return 0.0
    return result


def inside(p: Point, poly: list[Point]) -> bool:
    flag=False
    for a,b in segments(poly,True):
        if (a[1]>p[1])!=(b[1]>p[1]):
            x=a[0]+(p[1]-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if p[0]<x:flag=not flag
    return flag


def validate(case: dict) -> dict:
    ws=walls()
    min_wall=float('inf');min_vane=float('inf')
    adjacent_surface_gaps=[]
    reasons=[]
    for v in case['vanes']:
        p=v['validation_contour']
        own_cross=False
        for x,y in p:
            if not 0 <= x <= DRAWING_LIMIT_MM or not -DRAWING_LIMIT_MM <= y <= 0:
                reasons.append(f'Vane {v["index"]} leaves the central corner rectangle')
                break
        ss=segments(p,True)
        for j,(a,b) in enumerate(ss):
            for k in range(j+2,len(ss)):
                if j==0 and k==len(ss)-1:continue
                if crosses(a,b,*ss[k]):
                    reasons.append(f'Vane {v["index"]} uniformly scaled contour self-intersects')
                    own_cross=True
                    break
            if own_cross:break
        for wall in ws:
            min_wall=min(min_wall,poly_gap(p,wall,closed_q=False))
        for u in case['vanes'][:v['index']-1]:
            q=u['validation_contour']
            if inside(p[0],q) or inside(q[0],p):
                reasons.append(f'Vanes {u["index"]} and {v["index"]} contain one another')
            gap=poly_gap(p,q)
            min_vane=min(min_vane,gap)
            if u['index']==v['index']-1:
                adjacent_surface_gaps.append(gap)
    if min_wall<GEOMETRY_GUARD_MM: reasons.append(f'Wall gap {min_wall:.3f} mm < numerical guard')
    if min_wall<MIN_SURFACE_WALL_GAP_MM:
        reasons.append(f'Full airfoil wall gap {min_wall:.3f} mm < half-pitch floor {MIN_SURFACE_WALL_GAP_MM:.1f} mm')
    if min_vane<GEOMETRY_GUARD_MM:reasons.append(f'Vane gap {min_vane:.3f} mm < numerical guard')
    return dict(valid=not reasons,reasons=list(dict.fromkeys(reasons)),
                min_wall_gap_mm=min_wall,min_vane_gap_mm=min_vane,
                adjacent_surface_gaps_mm=adjacent_surface_gaps,
                wall_model='Dimensioned drawing interpreted in XY; verify against exact CAD walls',
                clearance_guard_mm=GEOMETRY_GUARD_MM,
                full_surface_wall_floor_mm=MIN_SURFACE_WALL_GAP_MM)


def export(case: dict, destination: Path) -> Path:
    result=validate(case)
    if not result['valid']:
        raise ValueError('Export blocked: '+ '; '.join(result['reasons']))
    if not destination.is_dir():
        raise ValueError(f'Export directory does not exist: {destination}')
    theta_number=f'{case["theta_deg"]:g}'
    le_number=f'{case["le_angle_deg"]:g}'
    combined_csv=destination/f'Uniform_Scaling_Vane_Fitting_{theta_number}_LE_{le_number}.csv'
    with combined_csv.open('w',newline='') as f:
        writer=csv.writer(f)
        for index,v in enumerate(case['vanes']):
            if index:
                writer.writerow([])          # one completely empty row between vanes
            for x,y in v['contour']:
                writer.writerow((f'{x/10:.8f}',f'{y/10:.8f}','0'))
    return combined_csv


def browser_gui(source: dict, initial_theta: float, initial_le_angle: float):
    """Dependency-free browser GUI; no Tk installation or adjacent CSV needed."""
    import http.server
    import urllib.parse
    import webbrowser

    page = r'''<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Five corner vanes — uniform scaling</title>
<style>body{font:16px system-ui;margin:24px auto;max-width:1100px;color:#1b2935;padding:0 16px}
h1{font-size:23px;margin:0 0 8px}p{margin:5px 0 16px}
section{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin:12px 0}
label{display:flex;gap:8px;align-items:center}input[type=range]{width:min(60vw,570px)}
button{padding:9px 15px;cursor:pointer}
#status{border-radius:5px;padding:12px;background:#edf2f7;white-space:pre-wrap}
#plot{width:100%;height:660px;border:1px solid #cbd5e1;margin-top:12px}
.note{font-size:13px;color:#52606d}</style></head><body>
<h1>Five bent NACA 0009 corner vanes — uniform scaling</h1>
<p>At theta 0°: five equal copies of the embedded 339.411 cm baseline vane with a 50 mm trailing-edge gap. At positive theta, both sliders set rays from the inner corner centre. All five chord lines stay parallel to the 45° baseline and have equal perpendicular spacing. The fit places the inner and outer vanes so their respective wall gaps are as close as possible to the vane-to-vane intervals, across the mean-camber, LE-ray and TE-ray measurements. The four intervals between corresponding vane points are equal within each measurement row by construction. The GUI shows the remaining RMS and worst-case mismatch; exact equality is not assumed. Airfoil contours retain at least 1035 mm wall clearance or the case is rejected. Each vane is uniformly scaled; exported XYZ is in cm.</p>
<section><label>Chord angle θ <input id="theta" type="range" min="__MIN_THETA__" max="__MAX_THETA__" step="1"><b id="thetaText"></b></label></section>
<section><label>LE angle from vertical <input id="leAngle" type="range" min="__MIN_LE_ANGLE__" max="__MAX_LE_ANGLE__" step="1"><b id="leAngleText"></b></label>
<button id="centerRays" type="button">Center LE/TE rays</button>
<button id="export" disabled>Export one XYZ CSV file</button></section>
<p class="note" id="centerHint"></p>
<div id="status">Computing geometry...</div><canvas id="plot"></canvas>
<p class="note">Theta 0° is a separate equal-vane reference; coincident LE/TE rays cannot form a positive chord. Center LE/TE rays sets LE to the nearest integer degree to 45° − θ/2, which balances the two ray angles around the 45° corner bisector. This is a geometric starting point, not a CFD optimum or a guarantee of equal wall gaps. Dashed gray segments are baseline chords; dashed green segments are current chords. Blue, orange and red connect corresponding LE, camber-midpoint and TE-gap-midpoint points across five vanes. Thin short wall lines at the three camber stations are parallel to the corner midline; thick purple LE and cyan TE wall lines follow their rays. For each measurement row with inner wall gap I, one of four equal vane intervals S, and outer wall gap O, the fit adds [(I−S)/2070]² + [(O−S)/2070]². It equally averages (1) these errors over 31 camber samples, (2) the LE-ray row, and (3) the TE-ray row. Thus both walls are fitted to the vane interval rather than merely to each other. A denser 301-point camber check reports the worst gap difference. The original 2070 mm pitch is not imposed; it only normalizes error units. Two free end-vane positions cannot generally satisfy every gap equality exactly under fixed ray angles and parallel chord lines. The TE camber endpoint is the midpoint between its two surfaces, so full contours are still checked against the walls. The 1 mm wall-to-spacing label and 1035 mm minimum full-surface wall clearance are geometric reporting/guard choices, not CFD mesh criteria. Changing LE angle also changes vane chord and scale. A CSV may be exported for exploratory CFD even when wall equality is unmet; it must not be described as a symmetric case. One CSV named Uniform_Scaling_Vane_Fitting_THETA_LE_ANGLE.csv is saved beside this file with blank rows between vanes. Close each TE with a straight segment in CAD and verify Fusion splines and the CFD mesh.</p>
<script>
const slider=document.querySelector('#theta'),leSlider=document.querySelector('#leAngle');
const status=document.querySelector('#status'),button=document.querySelector('#export');
const canvas=document.querySelector('#plot'),thetaText=document.querySelector('#thetaText'),leAngleText=document.querySelector('#leAngleText');
const centerRays=document.querySelector('#centerRays'),centerHint=document.querySelector('#centerHint');
let last=null,timer=null,requestId=0;
slider.value='__THETA__';leSlider.value='__LE_ANGLE__';
function clearPlot(message){
 const c=canvas.getContext('2d'),W=Math.max(350,canvas.clientWidth),H=660,dpr=devicePixelRatio||1;
 canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);c.setTransform(dpr,0,0,dpr,0,0);
 c.clearRect(0,0,W,H);c.fillStyle='#52606d';c.font='16px system-ui';c.fillText(message,20,36);
}
function plot(data){
 const c=canvas.getContext('2d'),W=Math.max(350,canvas.clientWidth),H=660,dpr=devicePixelRatio||1;
 canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,W,H);
 const points=[[0,0],...data.walls.flat(),...data.vanes.flatMap(v=>v.contour)];
 const minx=Math.min(...points.map(p=>p[0]))-400,maxx=Math.max(...points.map(p=>p[0]))+400;
 const miny=Math.min(...points.map(p=>p[1]))-400,maxy=Math.max(...points.map(p=>p[1]))+400;
 const k=Math.min((W-32)/(maxx-minx),(H-32)/(maxy-miny));
 const xy=p=>[16+(p[0]-minx)*k,H-16-(p[1]-miny)*k];
 function line(ps,color,width=1.5,dash=[]){c.beginPath();ps.forEach((p,i)=>{const [x,y]=xy(p);if(i)c.lineTo(x,y);else c.moveTo(x,y)});
   c.strokeStyle=color;c.lineWidth=width;c.setLineDash(dash);c.stroke();c.setLineDash([])}
 for(const wall of data.walls)line(wall,'#596579');
 for(const v of data.vanes)line([v.baseline_te,v.baseline_le],'#94a3b8',1.3,[4,5]);
 line([[0,0],[__BISECTOR_R__,-__BISECTOR_R__]],'#334155',1.5,[2,5]);
 if(!data.reference_only){
  line([[0,0],data.vanes.at(-1).le],'#2563eb',2,[6,5]);
  line([[0,0],data.vanes.at(-1).te],'#dc2626',2,[6,5]);
 }
 for(const v of data.vanes){const p=v.contour;c.beginPath();p.forEach((q,i)=>{const [x,y]=xy(q);if(i)c.lineTo(x,y);else c.moveTo(x,y)});c.closePath();
 c.fillStyle=data.valid?'#dbeafe':'#fee2e2';c.fill();c.strokeStyle=data.valid?'#075985':'#b91c1c';c.lineWidth=1.5;c.stroke();
 line([v.le,v.te],'#15803d',1.3,[3,4]);
 line(v.mean_camber,'#ea580c',1.2);
 const [mx,my]=xy(v.camber_midpoint);c.beginPath();c.arc(mx,my,3,0,Math.PI*2);c.fillStyle='#c2410c';c.fill();
 const [x,y]=xy(v.midpoint);c.fillStyle='#1e293b';c.font='12px system-ui';c.fillText(String(v.index),x,y)}
 line(data.vanes.map(v=>v.le),'#2563eb',1.6,[4,3]);
 line(data.vanes.map(v=>v.camber_midpoint),'#ea580c',1.8,[4,3]);
 line(data.vanes.map(v=>v.te),'#dc2626',1.6,[4,3]);
 for(const [j,color] of [['0','#9333ea'],['15','#ea580c'],['30','#0891b2']]){
   const feet=data.camber_end_wall_feet[j],k=Number(j);
   line([data.vanes[0].mean_camber[k],feet.inner],color,1,[2,4]);
   line([data.vanes.at(-1).mean_camber[k],feet.outer],color,1,[2,4]);
 }
 // Thick segments represent the additional LE/TE ray-wall measurements.
 line([data.vanes[0].le,data.inner_le_wall_foot],'#9333ea',2.5);
 line([data.vanes.at(-1).le,data.outer_le_wall_foot],'#9333ea',2.5);
 line([data.vanes[0].te,data.inner_te_wall_foot],'#0891b2',2.5);
 line([data.vanes.at(-1).te,data.outer_te_wall_foot],'#0891b2',2.5);
 const [ox,oy]=xy([0,0]);c.beginPath();c.arc(ox,oy,4,0,Math.PI*2);c.fillStyle='#111827';c.fill();
}
async function refresh(){
 const id=++requestId;
 const centeredLE=45-Number(slider.value)/2;
 centerHint.textContent=Number(slider.value)===0?'Theta 0° is the equal-vane reference.':'Ray-centered starting point: LE '+centeredLE.toFixed(1)+'° from vertical; TE '+(45+Number(slider.value)/2).toFixed(1)+'°. The 1° LE slider uses the nearest whole degree.';
 centerRays.disabled=Number(slider.value)===0;
 thetaText.textContent=Number(slider.value).toFixed(0)+'°';
 leAngleText.textContent=Number(leSlider.value).toFixed(0)+'°';button.disabled=true;
 try{const q=new URLSearchParams({theta:slider.value,le_angle:leSlider.value});
 const resp=await fetch('/case?'+q);const data=await resp.json();if(!resp.ok)throw Error(data.error);
 if(id!==requestId)return;
 last=data;button.disabled=!data.valid;
 const chords=data.vanes.map(v=>(v.chord_mm/10).toFixed(1)).join(', ');
 const angleLabel=data.reference_only?'MODIFIED BASELINE REFERENCE (five identical profiles; no LE/TE rays)':
   'LE from vertical '+data.le_angle_deg.toFixed(1)+'° | LE-to-TE angle at O '+data.measured_theta_deg.toFixed(1)+'°';
 const scales=data.vanes.map(v=>v.scale_factor.toFixed(3)).join(', ');
 const thicknesses=data.vanes.map(v=>(v.max_normal_thickness_mm/10).toFixed(2)).join(', ');
 const gaps=data.vanes.map(v=>v.te_gap_mm.toFixed(2)).join(', ');
 const relative=(100*data.source_max_normal_thickness_mm/data.source_chord_mm).toFixed(2);
 const balance=data.reference_only?'REFERENCE (no spacing fit)':data.spacing_match_met?'WALL / VANE GAPS MATCH WITHIN 1 mm':'WALL / VANE GAPS NOT EQUAL';
 status.textContent=(data.valid?'GEOMETRY VALID':'GEOMETRY REJECTED')+' | '+balance+' | '+angleLabel+'\n'+
 'Chords inner to outer (cm): '+chords+'\n'+
 'LE-to-TE chord angles (°), baseline 45.000: '+data.vanes.map(v=>v.chord_angle_deg.toFixed(3)).join(', ')+'\n'+
 'Uniform scale factors inner to outer: '+scales+'\n'+
 'Scaled maximum normal thicknesses (cm): '+thicknesses+'; thickness/chord: '+relative+'% for every vane\n'+
 'Trailing-edge gaps inner to outer (mm): '+gaps+'; baseline gap '+data.source_te_gap_mm.toFixed(2)+' mm\n'+
 'Perpendicular chord-line pitch (mm): '+data.chord_gaps_mm.map(g=>g.toFixed(1)).join(', ')+'; 45 points per vane\n'+
 'Finite chord-segment gaps (mm): '+data.finite_chord_gaps_mm.map(g=>g.toFixed(1)).join(', ')+'\n'+
 'Curved-surface gaps (mm): '+data.adjacent_surface_gaps_mm.map(g=>g.toFixed(1)).join(', ')+'\n'+
 'Camber six gaps inner / four equal intervals / outer (mm; midline direction):\n'+
 Object.entries(data.camber_six_gaps_mm).map(([name,g])=>'  '+name+': '+g.map(n=>n.toFixed(0)).join(' / ')).join('\n')+'\n'+
 'LE and TE six gaps inner / four equal intervals / outer (mm; along each ray):\n'+
 Object.entries(data.radial_six_gaps_mm).map(([name,g])=>'  '+name+': '+g.map(n=>n.toFixed(0)).join(' / ')).join('\n')+'\n'+
 'Largest inner-versus-outer difference (mm): camber '+data.camber_wall_pair_mismatch_mm.toFixed(1)+', LE/TE rays '+data.radial_wall_pair_mismatch_mm.toFixed(1)+', combined '+data.wall_pair_mismatch_mm.toFixed(1)+' (equality threshold '+data.wall_equality_tolerance_mm.toFixed(0)+' mm)\n'+
 'Largest wall-to-vane-spacing difference across 301 camber stations and LE/TE rays (mm): '+data.max_wall_to_spacing_mismatch_mm.toFixed(1)+(data.max_wall_to_spacing_mismatch_mm>207?' — visibly uneven; angles/clearance restrict the fit':'')+'\n'+
 (data.family_gap_rms_mm?'Wall-to-vane spacing RMS by group (mm): camber '+data.family_gap_rms_mm.Camber.toFixed(1)+', LE ray '+data.family_gap_rms_mm.LE.toFixed(1)+', TE ray '+data.family_gap_rms_mm.TE.toFixed(1)+' (one-third score weight each)\n':'')+
 'Euclidean corresponding-point spacing range (mm): '+data.camber_station_spacing_range_mm[0].toFixed(1)+' to '+data.camber_station_spacing_range_mm[1].toFixed(1)+'; four equal intervals at each station\n'+
 (data.max_possible_row_spacings_mm?'Maximum intervals under wall floor (mm): LE '+data.max_possible_row_spacings_mm.LE.toFixed(1)+', camber midpoint '+data.max_possible_row_spacings_mm.Camber.toFixed(1)+', TE '+data.max_possible_row_spacings_mm.TE.toFixed(1)+'\n':'')+
 (data.reference_only?'Equal-vane baseline reference':'Wall-to-vane spacing error RMS '+data.rms_gap_error_mm.toFixed(1)+' mm; squared-error score '+data.optimization_score.toFixed(4)+'; full-surface wall floor '+data.surface_wall_floor_mm.toFixed(0)+' mm')+'\n'+
 (data.valid?'Minimum wall gap '+data.wall_gap_mm.toFixed(1)+' mm; vane gap '+data.vane_gap_mm.toFixed(1)+' mm; wall-floor margin '+(data.wall_gap_mm-data.surface_wall_floor_mm).toFixed(1)+' mm'+(!data.reference_only&&data.wall_gap_mm-data.surface_wall_floor_mm<5?' — wall floor is limiting placement':''):data.reasons.join('; '));
 status.style.background=!data.valid?'#fee2e2':data.reference_only||data.spacing_match_met?'#dcfce7':'#fef3c7';plot(data);
 }catch(e){if(id===requestId){last=null;status.textContent='REJECTED: '+e.message;
 status.style.background='#fee2e2';clearPlot('No constructible vane at these angles.')}}
}
for(const control of [slider,leSlider])control.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(refresh,140)});
centerRays.addEventListener('click',()=>{leSlider.value=String(Math.round(45-Number(slider.value)/2));refresh()});
button.addEventListener('click',async()=>{button.disabled=true;try{const response=await fetch('/export',{method:'POST',headers:{'Content-Type':'application/json'},
 body:JSON.stringify({theta:Number(slider.value),le_angle:Number(leSlider.value)})});const r=await response.json();
 if(!response.ok)throw Error(r.error);status.textContent+='\nExported: '+r.csv;
 }catch(e){status.textContent+='\nExport failed: '+e.message}finally{button.disabled=!last?.valid}});
refresh();</script></body></html>'''
    page=(page.replace('__THETA__',str(min(max(initial_theta,GUI_MIN_THETA_DEG),GUI_MAX_THETA_DEG)))
              .replace('__MAX_THETA__',str(GUI_MAX_THETA_DEG))
              .replace('__MIN_THETA__',str(GUI_MIN_THETA_DEG))
              .replace('__LE_ANGLE__',str(min(max(initial_le_angle,GUI_MIN_LE_ANGLE_DEG),GUI_MAX_LE_ANGLE_DEG)))
              .replace('__MIN_LE_ANGLE__',str(GUI_MIN_LE_ANGLE_DEG))
              .replace('__MAX_LE_ANGLE__',str(GUI_MAX_LE_ANGLE_DEG))
              .replace('__BISECTOR_R__',str(round(DRAWING_LIMIT_MM-PAPER_RADIUS_MM+PAPER_RADIUS_MM/math.sqrt(2),6)))
              .replace('__BISECTOR_R__',str(round(DRAWING_LIMIT_MM-PAPER_RADIUS_MM+PAPER_RADIUS_MM/math.sqrt(2),6))))

    class Handler(http.server.BaseHTTPRequestHandler):
        def log_message(self, *_args): pass

        def send_json(self, value: dict, status: int=200):
            body=json.dumps(value).encode('utf-8')
            self.send_response(status)
            self.send_header('Content-Type','application/json; charset=utf-8')
            self.send_header('Content-Length',str(len(body)))
            self.end_headers();self.wfile.write(body)

        def make_case(self, theta: float, le_angle: float) -> tuple[dict,dict]:
            case=design(theta,source,le_angle)
            return case,validate(case)

        def do_GET(self):
            u=urllib.parse.urlparse(self.path)
            if u.path=='/':
                b=page.encode('utf-8')
                self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8')
                self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
                return
            if u.path!='/case':
                self.send_json({'error':'Unknown path'},404);return
            try:
                q=urllib.parse.parse_qs(u.query)
                case,check=self.make_case(float(q['theta'][0]),float(q['le_angle'][0]))
                self.send_json(dict(valid=check['valid'],reasons=check['reasons'],
                                    reference_only=case['reference_only'],
                                    measured_theta_deg=case['measured_theta_deg'],
                                    le_angle_deg=case['le_angle_deg'],
                                    source_chord_mm=source['chord_mm'],
                                    source_te_gap_mm=source['te_gap_mm'],
                                    source_max_normal_thickness_mm=source['max_normal_thickness_mm'],
                                    chord_gaps_mm=case['chord_gaps_mm'],
                                    finite_chord_gaps_mm=case['finite_chord_gaps_mm'],
                                    adjacent_surface_gaps_mm=check['adjacent_surface_gaps_mm'],
                                    row_spacings_mm=case['row_spacings_mm'],
                                    camber_station_spacing_range_mm=case['camber_station_spacing_range_mm'],
                                    camber_six_gaps_mm=case['camber_six_gaps_mm'],
                                    radial_six_gaps_mm=case['radial_six_gaps_mm'],
                                    camber_max_gap_mismatch_mm=case['camber_max_gap_mismatch_mm'],
                                    camber_wall_pair_mismatch_mm=case['camber_wall_pair_mismatch_mm'],
                                    radial_wall_pair_mismatch_mm=case['radial_wall_pair_mismatch_mm'],
                                    wall_pair_mismatch_mm=case['wall_pair_mismatch_mm'],
                                    max_wall_to_spacing_mismatch_mm=case['max_wall_to_spacing_mismatch_mm'],
                                    spacing_match_met=case['spacing_match_met'],
                                    wall_equality_met=case['wall_equality_met'],
                                    wall_equality_tolerance_mm=case['wall_equality_tolerance_mm'],
                                    camber_end_wall_feet=case['camber_end_wall_feet'],
                                    point_wall_gaps_mm=case['point_wall_gaps_mm'],
                                    optimization_score=case['optimization_score'],
                                    rms_gap_error_mm=case['rms_gap_error_mm'],
                                    family_gap_rms_mm=case['family_gap_rms_mm'],
                                    max_possible_row_spacings_mm=case['max_possible_row_spacings_mm'],
                                    surface_wall_floor_mm=case['surface_wall_floor_mm'],
                                    inner_midline_foot=case['inner_midline_foot'],
                                    outer_midline_foot=case['outer_midline_foot'],
                                    inner_le_wall_foot=case['inner_le_wall_foot'],
                                    outer_le_wall_foot=case['outer_le_wall_foot'],
                                    inner_te_wall_foot=case['inner_te_wall_foot'],
                                    outer_te_wall_foot=case['outer_te_wall_foot'],
                                    wall_gap_mm=check['min_wall_gap_mm'],vane_gap_mm=check['min_vane_gap_mm'],
                                    walls=walls(),vanes=[dict(index=v['index'],chord_mm=v['chord_mm'],
                                    chord_angle_deg=v['chord_angle_deg'],
                                    midpoint=v['midpoint'],station=v['station'],
                                    scale_factor=v['scale_factor'],
                                    max_normal_thickness_mm=v['max_normal_thickness_mm'],
                                    te_gap_mm=v['te_gap_mm'],
                                    le=v['le'],te=v['te'],
                                    mean_camber=v['mean_camber'],
                                    camber_midpoint=v['camber_midpoint'],
                                    baseline_le=v['baseline_le'],baseline_te=v['baseline_te'],
                                    contour=v['contour']) for v in case['vanes']]))
            except (KeyError,IndexError,ValueError,OverflowError) as exc:
                self.send_json({'error':str(exc)},400)

        def do_POST(self):
            if self.path!='/export':
                self.send_json({'error':'Unknown path'},404);return
            try:
                length=int(self.headers.get('Content-Length','0'))
                if not 0<length<=4096:raise ValueError('Invalid request size')
                args=json.loads(self.rfile.read(length))
                case,_=self.make_case(float(args['theta']),float(args['le_angle']))
                csv_path=export(case,Path(__file__).resolve().parent)
                self.send_json({'csv':str(csv_path)})
            except (KeyError,TypeError,ValueError,OverflowError,OSError) as exc:
                self.send_json({'error':str(exc)},400)

    with http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler) as server:
        url=f'http://127.0.0.1:{server.server_port}/'
        print('Open the corner-vane GUI at',url,flush=True)
        if not webbrowser.open(url):
            print('If the browser did not open automatically, paste that address into your browser.',flush=True)
        try:server.serve_forever()
        except KeyboardInterrupt:pass


def main():
    import sys
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--theta',type=float,default=20.0,help='Angle between LE and TE rays (0-40 degrees); 0 shows five equal-chord baseline vanes')
    parser.add_argument('--le-angle',type=float,default=DEFAULT_LE_ANGLE_DEG,
                        help='LE ray angle from downward vertical toward +X (0-90 degrees; default 30)')
    parser.add_argument('--export',type=Path,help='Export one combined CSV directly to this existing directory')
    parser.add_argument('--gui',action='store_true',help='Open the local browser slider')
    args=parser.parse_args()
    source=load_source()
    print(f'CSV validated: {source["point_count"]} points, chord {source["chord_mm"]:.5f} mm, TE gap {source["te_gap_mm"]:.5f} mm, maximum modified-baseline fit discrepancy {source["max_reconstruction_error_mm"]:.6f} mm')
    if args.gui or len(sys.argv)==1:
        browser_gui(source,args.theta,args.le_angle)
        return
    case=design(args.theta,source,args.le_angle)
    check=validate(case)
    if case['reference_only']:
        print(f'Five identical 50 mm TE baselines on original chord lines; 0° is a reference without corner LE/TE rays; pitch: {PITCH_MM:.1f} mm')
    else:
        print(f'Angle at O: {case["measured_theta_deg"]:.5f}°; LE from vertical: {case["le_angle_deg"]:.5f}°; equal parallel chord-line pitch: {case["chord_gap_mm"]:.3f} mm')
        print('Six midline-direction gaps [inner, 4 inter-vane, outer] (mm):',case['camber_six_gaps_mm'])
        print('Six LE/TE-ray gaps [inner, 4 inter-vane, outer] (mm):',case['radial_six_gaps_mm'])
        print('Worst wall-gap pair difference, 301 camber samples (mm):',round(case['camber_wall_pair_mismatch_mm'],2))
        print('Worst LE/TE ray wall-gap pair difference (mm):',round(case['radial_wall_pair_mismatch_mm'],2))
        print('Combined worst wall-gap pair difference (mm):',round(case['wall_pair_mismatch_mm'],2))
        print('Largest wall-to-vane-spacing mismatch (mm):',round(case['max_wall_to_spacing_mismatch_mm'],2))
        print('Wall-to-vane-spacing RMS by group (mm):',case['family_gap_rms_mm'])
        print('Wall equality within 1 mm:',case['wall_equality_met'])
        print('Largest six-gap wall/vane mismatch over all 31 stations (mm):',round(case['camber_max_gap_mismatch_mm'],2))
        print('Euclidean corresponding-camber spacing range (mm):',case['camber_station_spacing_range_mm'])
        print('Maximum possible intervals under wall floor (mm):',case['max_possible_row_spacings_mm'])
        print(f'Wall-to-vane spacing error RMS {case["rms_gap_error_mm"]:.2f} mm; squared-error fit score {case["optimization_score"]:.6f}; full-surface wall floor {case["surface_wall_floor_mm"]:.1f} mm')
    for v in case['vanes']:
        print(f'Vane {v["index"]}: chord {v["chord_mm"]/10:.2f} cm; scale {v["scale_factor"]:.5f}; TE gap {v["te_gap_mm"]:.2f} mm; thickness {v["max_normal_thickness_mm"]/10:.2f} cm; LE mm {v["le"]}; TE mm {v["te"]}; {len(v["contour"])} XYZ points')
    print('Geometry', 'VALID' if check['valid'] else 'REJECTED',check)
    if args.export: print('Exported to',export(case,args.export))
    elif not check['valid']:raise SystemExit(2)


if __name__=='__main__':main()
